function treeOutline(root: TreeNode | null): number[] {
  if (!root) return [];
  const isLeaf = (n: TreeNode) => !n.left && !n.right;
  if (isLeaf(root)) return [root.val];
  const out = [root.val];
  for (let n = root.left; n && !isLeaf(n); n = n.left ?? n.right) out.push(n.val);
  const stack: TreeNode[] = [root];
  while (stack.length) {
    const n = stack.pop()!;
    if (isLeaf(n)) out.push(n.val);
    if (n.right) stack.push(n.right); // right first, so left is visited first
    if (n.left) stack.push(n.left);
  }
  const right: number[] = [];
  for (let n = root.right; n && !isLeaf(n); n = n.right ?? n.left) right.push(n.val);
  return out.concat(right.reverse());
}

