class Solution:
    def treeOutline(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        is_leaf = lambda n: not n.left and not n.right
        if is_leaf(root):
            return [root.val]
        out = [root.val]
        n = root.left
        while n and not is_leaf(n):
            out.append(n.val)
            n = n.left or n.right
        stack = [root]
        while stack:
            n = stack.pop()
            if is_leaf(n):
                out.append(n.val)
            if n.right:
                stack.append(n.right)  # right first, so left is visited first
            if n.left:
                stack.append(n.left)
        right = []
        n = root.right
        while n and not is_leaf(n):
            right.append(n.val)
            n = n.right or n.left
        return out + right[::-1]

