function treeOutline(root: TreeNode | null): number[] {
  if (!root) return [];
  if (!root.left && !root.right) return [root.val];
  const out = [root.val];
  const walk = (n: TreeNode | null, onLeft: boolean, onRight: boolean): void => {
    if (!n) return;
    const leaf = !n.left && !n.right;
    if (leaf) { out.push(n.val); return; }
    if (onLeft) out.push(n.val);
    // a left-edge node's right child stays on the edge only if there is no left child
    walk(n.left, onLeft, onRight && !n.right);
    walk(n.right, onLeft && !n.left, onRight);
    if (onRight) out.push(n.val);
  };
  walk(root.left, true, false);
  walk(root.right, false, true);
  return out;
}

